import{_ as t,o as e,c as i,a5 as s}from"./chunks/framework.a5no_H3L.js";const b=JSON.parse('{"title":"常见问题排查","description":"RabbitMQ 的线上故障很少以明确报错的形式出现，多数收敛成几种表象：消息堆积、生产者被阻塞、连接失败等。排查的思路是先看队列全局状态缩小故障范围，再沿链路逐段验证，最后用一条可观测的指标确认修复生效。","frontmatter":{},"headers":[],"relativePath":"rabbitmq/08-operations/chapter-03-troubleshooting.md","filePath":"rabbitmq/08-operations/chapter-03-troubleshooting.md"}'),r={name:"rabbitmq/08-operations/chapter-03-troubleshooting.md"};function o(l,a,n,d,c,p){return e(),i("div",null,[...a[0]||(a[0]=[s(`<h1 id="常见问题排查" tabindex="-1" data-src-line="1" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md">常见问题排查 <a class="header-anchor" href="#常见问题排查" aria-label="Permalink to &quot;常见问题排查&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md"><p data-src-line="3" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md">RabbitMQ 的线上故障很少以明确报错的形式出现，多数收敛成几种表象：消息堆积、生产者被阻塞、连接失败等。排查的思路是先看队列全局状态缩小故障范围，再沿链路逐段验证，最后用一条可观测的指标确认修复生效。</p></blockquote><h2 id="_1-先看三列-缩小排查范围" tabindex="-1" data-src-line="5" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md">1. 先看三列，缩小排查范围 <a class="header-anchor" href="#_1-先看三列-缩小排查范围" aria-label="Permalink to &quot;1. 先看三列，缩小排查范围&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rabbitmqctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list_queues</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> messages_ready</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> messages_unacknowledged</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> consumers</span></span></code></pre></div><p data-src-line="11" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md">同一个「队列堆积」现象，这三列的组合会把排查方向引向不同的环节。</p><ul data-src-line="13" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md"><li data-src-line="13" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md"><code>consumers</code> 为 0，说明当前队列没有注册消费者。先检查消费者进程是否存活、连接是否建立，再确认它声明的队列名、路由键与生产者是否一致。队列里消息再多，此时也应先排查消费端。</li><li data-src-line="14" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md"><code>consumers</code> 大于 0、<code>messages_unacknowledged</code> 基本为 0、<code>messages_ready</code> 上涨，说明消息进入队列的速度可能超过实际消费速度，再结合投递速率和处理耗时确认原因。</li><li data-src-line="15" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md"><code>messages_unacknowledged</code> 持续上涨，说明消息已投递但尚未确认。结合持续时间、处理耗时和确认速率，判断是消费变慢还是确认卡住，再排查消费者线程阻塞、外部依赖超时等可能原因。</li></ul><p data-src-line="17" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md">单次快照只能反映当前状态，对同一队列间隔采样几次，才能确认消息是否在持续堆积。</p><h2 id="_2-消息堆积" tabindex="-1" data-src-line="19" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md">2. 消息堆积 <a class="header-anchor" href="#_2-消息堆积" aria-label="Permalink to &quot;2. 消息堆积&quot;">​</a></h2><p data-src-line="21" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md">堆积是结果不是原因。确认是第 1 节里的哪种组合后，分别处理。</p><p data-src-line="23" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md"><strong>没有消费者</strong>。先确认消费者进程是否存活，再确认它声明的队列名、路由键与生产者是否一致。如果生产者和消费者都声明同一个队列，但队列的持久化属性等声明参数不一致，RabbitMQ 会返回 <code>PRECONDITION_FAILED</code> 并关闭该信道，而不是建立不了 TCP 连接。检查服务端日志和客户端异常，确认双方声明一致。</p><p data-src-line="25" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md"><strong>消费者太慢</strong>。先判断是单条处理速度不足，还是消费并发不够，再决定优化处理逻辑还是横向加消费者。<code>prefetch</code> 不改变单条业务处理速度，它决定消费者最多同时持有的未确认消息数。把 <code>prefetch</code> 从 1 调到 100 不会让处理变快，只是让更多消息滞留在消费者端。先测出单个消费者的真实处理速率，再决定加几个消费者。</p><p data-src-line="27" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md"><strong>未确认消息持续增加</strong>。<code>messages_unacknowledged</code> 只涨不降时，去查消费者线程栈和它的外部依赖。如果同一批消息反复出现，检查消费者是否持续 nack 或 reject 并选择重新入队，或者连接、信道是否频繁关闭。结合消息的 <code>redelivered</code> 标记、死信队列和重试策略，确认是重复投递还是重试循环，而不是简单归因于 TTL 或重试上限没配好。</p><h2 id="_3-消息丢失" tabindex="-1" data-src-line="29" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md">3. 消息丢失 <a class="header-anchor" href="#_3-消息丢失" aria-label="Permalink to &quot;3. 消息丢失&quot;">​</a></h2><p data-src-line="31" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md">排查消息丢失，先确定消息最后一个能够被证实到达的环节。这个环节只是当前的证据边界，丢失点就在它之后的链路里，再逐段检查确认、路由和存储行为。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Producer ──confirm──▶ Broker ──存储与路由──▶ Queue ──deliver──▶ Consumer ──ack──▶ 完成</span></span></code></pre></div><ul data-src-line="37" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md"><li data-src-line="37" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md">Producer 到 Broker。开没开 publisher confirm。没开，生产者不知道消息是否被 broker 接受，发送途中丢失的消息无从发现。publisher confirm 的语义随队列类型不同：持久化消息路由到 durable classic queue 时，确认返回即已落盘；Quorum Queue 则要等多数副本接受并确认。它不代表消费者已经处理了这条消息。</li><li data-src-line="38" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md">Broker 落盘。经典队列要 durable 队列配 persistent 消息，重启后消息才保留，两者缺一不可。只声明 durable 队列、不设 persistent 消息，重启后消息照样丢，这个组合最容易被误认为「已经持久化了」。Quorum Queue 的消息始终持久化，不依赖消息的 persistent 属性。</li><li data-src-line="39" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md">Broker 到 Consumer。ack 模式。自动 ack 下消息一投递就被确认，消费者进程在处理中途崩溃，这条消息不会重投。</li><li data-src-line="40" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md">Consumer 处理。手动 ack 的时机。处理完再 ack，别在取到消息的那一刻就 ack。</li></ul><p data-src-line="42" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md">优先检查生产者是否收到发布确认，再检查消息是否进入目标队列，最后确认消费者是否处理成功并完成确认，按最后一个可验证的环节缩小范围。</p><h2 id="_4-生产者被阻塞" tabindex="-1" data-src-line="44" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md">4. 生产者被阻塞 <a class="header-anchor" href="#_4-生产者被阻塞" aria-label="Permalink to &quot;4. 生产者被阻塞&quot;">​</a></h2><p data-src-line="46" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md">RabbitMQ 需要区分瞬时流控和资源告警。发布速度超过服务端处理能力时，连接会进入 flow 状态；内存使用超过 <code>vm_memory_high_watermark</code>，或可用磁盘低于 <code>disk_free_limit</code> 时，节点触发资源告警并阻塞发布连接。现象都是生产者突然发不出消息，连接却还活着。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rabbitmq-diagnostics</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rabbitmq-diagnostics</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alarms</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rabbitmq-diagnostics</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> memory_breakdown</span></span></code></pre></div><p data-src-line="54" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md">看 <code>vm_memory_high_watermark</code>、<code>disk_free_limit</code> 的配置值，再对比 status 输出里的内存与磁盘使用情况，判断是内存告警、磁盘告警还是瞬时流控。</p><p data-src-line="56" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md">内存告警的根因通常是队列堆积把消息压进了内存。RabbitMQ 4.3 的默认相对内存水位是 0.6，达到后直接阻塞发布连接，不存在先刷盘、到更高水位再阻塞的过程。临时缓解是消费掉堆积消息。把水位调高只是推迟阻塞，不解决堆积，反而让 broker 更晚暴露问题。容器环境还要确认 RabbitMQ 检测到的内存与容器实际限制一致。</p><p data-src-line="58" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md">磁盘告警的根因是磁盘空间低于 <code>disk_free_limit</code>。这个值默认 50MB，只适合开发环境，对生产过低，磁盘一到阈值 broker 就拒绝写入。解决是清理磁盘或扩容，并按磁盘容量、写入速率和运维响应时间设一个真实的安全余量，让运维在真正写满之前有时间介入。处理后确认告警解除、发布连接不再持续 blocked、发布确认恢复正常，同时观察队列堆积和节点资源变化，避免告警解除后再次触发。</p><h2 id="_5-连接失败与认证错误" tabindex="-1" data-src-line="60" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md">5. 连接失败与认证错误 <a class="header-anchor" href="#_5-连接失败与认证错误" aria-label="Permalink to &quot;5. 连接失败与认证错误&quot;">​</a></h2><p data-src-line="62" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md">现象都是连不上，但发生在不同协议层，排查路径不同。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -vz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5672</span></span></code></pre></div><p data-src-line="68" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md">TCP 连接失败。<code>nc -vz</code> 无法建立 TCP 连接，根据具体错误区分是端口拒绝、连接超时还是网络不可达，再查 broker 是否在监听、监听地址、端口和防火墙规则。配置了 <code>listeners.tcp</code> 绑定具体 IP 后，客户端连错 IP 也会失败，这属于配置问题而非 broker 故障。</p><p data-src-line="70" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md">TCP 已建立但 AMQP 握手失败。<code>nc</code> 能连上，客户端握手却失败，查客户端异常和服务端日志，区分协议不匹配、TLS 配置错误、连接资源不足。连接数接近上限时，先查是泄漏还是真实流量增长，直接调大上限会掩盖泄漏。</p><p data-src-line="72" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md">认证或授权失败。错误信息是 <code>ACCESS_REFUSED</code> 而不是 refused，这是用户名密码、vhost 权限或具体操作授权的问题，和网络无关。guest 用户默认只允许本地登录，远程用 guest 会得到这个错误。</p><h2 id="_6-慢消费者" tabindex="-1" data-src-line="74" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md">6. 慢消费者 <a class="header-anchor" href="#_6-慢消费者" aria-label="Permalink to &quot;6. 慢消费者&quot;">​</a></h2><p data-src-line="76" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md">「慢」和「堆积」的区别在于，慢消费者的队列可能不堆积（流量本身低），但单条消息端到端延迟高。排查重点在消费者自身的处理链路。</p><ul data-src-line="78" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md"><li data-src-line="78" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md">消费者日志里单条处理耗时的分布。</li><li data-src-line="79" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md">外部依赖的延迟，数据库慢查询、API 超时。</li><li data-src-line="80" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md">prefetch 是否过低限制了消费者的在途消息数量。手动确认模式下，prefetch 为 1 意味着消费者最多持有一条未确认消息，处理完成并 ack 后 broker 才能投递下一条。处理快、网络延迟相对高时，这个确认往返的空窗占比可观，可能限制吞吐。可在观察处理耗时、确认速率的同时逐步调高 prefetch 并压测。</li></ul><h2 id="_7-网络分区" tabindex="-1" data-src-line="82" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md">7. 网络分区 <a class="header-anchor" href="#_7-网络分区" aria-label="Permalink to &quot;7. 网络分区&quot;">​</a></h2><p data-src-line="84" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md">集群节点互相认为对方失联时，队列行为和单机完全不同。RabbitMQ 4.3 起集群元数据与 Quorum Queue 都基于 Raft，判断分区要结合节点可达性和多数派状态，不再依赖旧版的 <code>partitions</code> 字段。具体处理策略见<a href="./../07-clustering/chapter-04-network-partition.html">网络分区</a>。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rabbitmq-diagnostics</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cluster_status</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rabbitmq-queues</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quorum_status</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">queu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p data-src-line="91" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md"><code>cluster_status</code> 列出可达节点，不可达节点会从列表中缺失。<code>quorum_status</code> 查看指定队列的领导者与副本状态。</p><p data-src-line="93" data-src-file="rabbitmq/08-operations/chapter-03-troubleshooting.md">分区时不要先想着修数据，先确认自己处在多数派还是少数派。多数派上需要共识的操作可以正常推进；少数派失去多数派后，这些操作（如写入）无法推进，别在少数派上做写操作，等网络恢复后再处理。</p>`,37)])])}const m=t(r,[["render",o]]);export{b as __pageData,m as default};
